<script>
 import {onDestroy} from 'svelte';
 let {snapshots=[],request}=$props();let opened=$state(''),url=$state(''),busy=$state(false),error=$state('');let alive=true;
 async function open(clip){if(!request||busy)return;busy=true;error='';try{const blob=await request('/inbox/clips/assets/'+encodeURIComponent(clip.assetId),{responseType:'blob'});if(!alive)return;if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(blob);opened=clip.id;}catch(e){if(alive)error=e.message;}finally{if(alive)busy=false;}}
 onDestroy(()=>{alive=false;if(url)URL.revokeObjectURL(url);});
</script>
{#if snapshots.length}<section class="clips" aria-label="Retained MP4 clips"><h3>Saved source clips</h3><p>Rendered from supplied files. Permission notes are retained; no publication or music clearance is implied.</p>{#if error}<p role="alert">{error}</p>{/if}{#each snapshots as clip(clip.id)}<article><h4>{clip.proposal.caption||'Source clip'}</h4><p>{clip.proposal.startSeconds}–{clip.proposal.endSeconds} seconds · 9:16 MP4 · segment revision {clip.proposalRevision}</p>{#if request}<button disabled={busy} onclick={()=>open(clip)}>{busy?'Opening…':'Play saved MP4'}</button>{/if}{#if opened===clip.id&&url}<video src={url} controls playsinline aria-label="Retained saved MP4"><track kind="captions"/></video><a href={url} download={`clip-${clip.id}.mp4`}>Download to share</a>{/if}<details><summary>Inputs and permission notes</summary>{#each clip.inputAssets as asset(asset.id)}<p>{asset.name} · {asset.kind}</p><p>{asset.rightsDeclaration}</p><small>SHA-256 {asset.sha256}</small>{/each}<p>Source audio {Math.round(clip.proposal.videoGain*100)}% · recording audio {Math.round(clip.proposal.audioGain*100)}%</p></details></article>{/each}</section>{/if}
<style>.clips article{border-left:2px solid #bdcbb4;padding-left:12px;margin:16px 0}.clips p{line-height:1.6;font-size:13px}.clips h4{margin:8px 0}video{display:block;width:100%;max-width:320px;max-height:500px;margin:12px 0;background:#111}small{display:block;overflow-wrap:anywhere;color:#69765f}summary{cursor:pointer;font-size:13px;margin-top:12px}</style>
